import math
import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the tanh-approximation GELU activation:
#
#   y = 0.5 * x * (1 + tanh( sqrt(2/pi) * (x + 0.044715 * x^3) ))
#
# tanh(z) is evaluated as (e^{2z} - 1) / (e^{2z} + 1), with
#   e^{2z} = 2^{2z * log2(e)}   computed via ex2.approx.ftz.f32
#
# The kernel processes the tensor in float4 (16-byte) chunks for
# throughput, with a scalar tail loop handling any remainder elements.
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry gelu_kernel(
    .param .u64 X_ptr,
    .param .u64 Y_ptr,
    .param .s64 N
)
{
    .reg .pred %p<5>;
    .reg .f32  %f<100>;
    .reg .b32  %r<10>;
    .reg .b64  %rd<40>;

    ld.param.u64 %rd0, [X_ptr];
    ld.param.u64 %rd1, [Y_ptr];
    ld.param.s64 %rd2, [N];

    cvta.to.global.u64 %rd3, %rd0;
    cvta.to.global.u64 %rd4, %rd1;

    // tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r0, %ctaid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %tid.x;
    mad.lo.s32 %r3, %r0, %r1, %r2;
    cvt.s64.s32 %rd5, %r3;

    // stride = blockDim.x * gridDim.x
    mov.u32 %r4, %nctaid.x;
    mul.lo.s32 %r5, %r1, %r4;
    cvt.s64.s32 %rd6, %r5;

    // Nvec = N / 4 ; rem_start = Nvec * 4
    shr.s64 %rd7, %rd2, 2;
    shl.b64 %rd8, %rd7, 2;

    // constants
    mov.f32 %f0, 0.044715;                 // a
    mov.f32 %f1, 0.7978845608028654;       // sqrt(2/pi)
    mov.f32 %f2, 1.0;                      // one
    mov.f32 %f3, 0.5;                      // half
    mov.f32 %f4, 2.8853900817779268;       // 2 * log2(e)

    mov.u64 %rd9, %rd5;

VEC_LOOP:
    setp.ge.s64 %p0, %rd9, %rd7;
    @%p0 bra VEC_DONE;

    shl.b64 %rd10, %rd9, 4;
    add.s64 %rd11, %rd3, %rd10;
    add.s64 %rd12, %rd4, %rd10;

    ld.global.v4.f32 {%f10, %f11, %f12, %f13}, [%rd11];

