    mul.f32     %f23, %f22, %f1;
    mul.f32     %f24, %f23, %f4;
    ex2.approx.ftz.f32 %f25, %f24;
    sub.f32     %f26, %f25, %f2;
    add.f32     %f27, %f25, %f2;
    rcp.approx.ftz.f32 %f28, %f27;
    mul.f32     %f29, %f26, %f28;
    add.f32     %f30, %f29, %f2;
    mul.f32     %f31, %f10, %f3;
    mul.f32     %f90, %f31, %f30;

