    add.s64 %rd9, %rd9, %rd6;
    bra.uni VEC_LOOP;

VEC_DONE:

    // remainder scalar loop
    add.s64 %rd14, %rd8, %rd5;

REM_LOOP:
    setp.ge.s64 %p1, %rd14, %rd2;
    @%p1 bra REM_DONE;

    shl.b64 %rd15, %rd14, 2;
    add.s64 %rd16, %rd3, %rd15;
    add.s64 %rd17, %rd4, %rd15;

    ld.global.f32 %f60, [%rd16];

