_MODULE = None


def _get_module() -> PtxModule:
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Look up the compiled kernel entry to validate the PTX module."""
    module = _get_module()
    return module.function("gelu_kernel")


class ModelNew(nn.Module):
    """
    GELU (tanh approximation) implemented with a hand-authored PTX kernel
    executed through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self) -> None:
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        y = torch.empty_like(x_c)

        N = x_c.numel()

        threads = 256
        Nvec = N // 4
        blocks_needed = (Nvec + threads - 1) // threads
        if blocks_needed < 1:
            blocks_needed = 1
        blocks = min(blocks_needed, 65535 * 32)

        module = _get_module()
        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            "gelu_kernel",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            args=(u64(x_c.data_ptr()), u64(y.data_ptr()), i64(N)),
            stream=stream,
        )

        return y
